                                                                                                                                                                                                                                                                                      'із '
                                                                                                                                                                                                                                                                                      'ключовими '
                                                                                                                                                                                                                                                                                      'моментами, '
                                                                                                                                                                                                                                                                                      'психологічний '
                                                                                                                                                                                                                                                                                      'розбір '
                                                                                                                                                                                                                                                                                      '(помста, '
                                                                                                                                                                                                                                                                                      'нервовість '
